    """
    Implements a recursive backtracking algorithm for regex matching.
    Supports literal characters, '.', '*', and '+'.
    The algorithm efficiently handles overlapping subproblems using memoization.
    """

    memo = {}

    def is_match(p: str, t: str) -> bool:
        if (p, t) in memo:
            return memo[(p, t)]

        if not p:
            result = not t
        else:
